SELECT so.id, so.code, so.so_id AS soId, so.so_code AS soCode, so.source_code AS sourceCode, so.source_type AS sourceType, so.source_id AS sourceId, so.order_type AS orderType, so.approve_status AS approveStatus, so.warehouse_org_name AS warehouseOrgName, so.carrier_id AS carrierId, so.invalid_status AS invalidStatus, so.plan_delivery_date AS planDeliveryDate, so.actual_delivery_date AS actualDeliveryDate, so.pack_date AS packDate, so.warehouse_id AS warehouseId, so.warehouse_name AS warehouseName, so.approve_user_name AS approveUserName, so.create_user_name AS createUserName, so.create_time AS createTime, so.track_no AS trackNo, so.seller_id AS sellerId, so.seller_name AS sellerName, so.customer_id AS customerId, so.bill_date AS billDate, so.customer_order_no AS customerOrderNo, sod.id as detailId, so.sales_dept_id AS salesDeptId, sod.id as detailId, sod.sku_id AS skuId, sod.sku_no AS skuNo, sod.plan_qty AS planQty, sod.actual_qty AS actualQty, sod.price, sod.tax_rate as taxRate, sod.amount, sod.currency, sod.currency_symbol as currencySymbol, sod.all_amount_local_currency as allAmountLocalCurrency, sod.exchange_rate as exchangeRate, sod.so_detail_id as soDetailId, sod.source_detail_id AS sourceDetailId, sod.warehouse_location AS warehouseLocation FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id=sod.main_id AND sod.is_deleted=FALSE WHERE so.is_deleted=FALSE
AND sod.sku_no IN
#{skuNo}
AND so.code ILIKE concat('%', #{params.code}::text ,'%')
AND so.customer_order_no ILIKE concat('%', #{params.customerOrderNo}::text ,'%')
AND so.so_code ILIKE concat('%', #{params.soCode}::text ,'%')
AND so.order_type =#{params.orderType}
AND so.sales_dept_id =#{params.salesDeptId}
AND so.approve_status IN
#{approveStatus}
AND so.invalid_status =#{params.invalidStatus}
AND so.customer_id IN
#{customerId}
AND so.seller_id IN
#{item}
AND so.warehouse_id IN
#{warehouseId}
AND so.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.create_time
AND so.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > so.bill_date
AND so.create_user_id IN
#{createUserId}
AND so.approve_status IN
#{approve}
AND so.track_no IN
#{item}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
so.create_time DESC

